<script setup>import{useForm,router}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';const props=defineProps({slides:Array,products:Array,services:Array,view:String,counts:Object}),form=useForm({item_type:'product',item_id:'',eyebrow:'',badge:'',headline:'',description:'',primary_label:'',secondary_label:'',is_active:true,sort_order:0});const items=()=>form.item_type==='product'?props.products:props.services;const submit=()=>form.post('/admin/carousel',{onSuccess:()=>form.reset()});</script><template><AdminLayout><p class="section-kicker">Homepage</p><h1 class="section-title">Carousel</h1><div class="mt-6 grid gap-5 lg:grid-cols-[360px_1fr]"><form class="card h-fit p-5" @submit.prevent="submit"><h2 class="font-black">Add slide</h2><div class="mt-4 grid gap-3"><select v-model="form.item_type" class="input"><option value="product">Product</option><option value="service">Service</option></select><select v-model="form.item_id" class="input"><option value="">Select item</option><option v-for="i in items()" :key="i.id" :value="i.id">{{i.name}}</option></select><input v-model="form.eyebrow" class="input" placeholder="Eyebrow"><input v-model="form.headline" class="input" placeholder="Custom headline"><textarea v-model="form.description" class="input" placeholder="Description"></textarea><input v-model.number="form.sort_order" type="number" class="input" placeholder="Sort order"><button class="btn-primary">Add slide</button></div></form><div class="grid gap-3"><div v-for="s in slides" :key="s.id" class="card flex items-center justify-between gap-4 p-4"><div><p class="text-xs font-black uppercase text-prinx-600">{{s.item_type}}</p><b>{{s.headline||s.product?.name||s.service?.name}}</b><p class="text-sm text-slate-500">{{s.description}}</p></div><button class="font-bold text-red-600" @click="router.delete(`/admin/carousel/${s.id}`)">Trash</button></div></div></div></AdminLayout></template>
